import { AJNA_TENANT_ID } from '../tenant.ts';
import { defaultSettings } from './defaults.ts';
import { settingKeys } from './schema.ts';

function sqlLiteral(value: string): string {
  return `'${value.replaceAll("'", "''")}'`;
}

/** Renders the idempotent settings seed. Existing values are never overwritten. */
export function renderSettingsSeed(tenantId: string = AJNA_TENANT_ID): string {
  const rows = settingKeys.map(
    (key) =>
      `  (${sqlLiteral(tenantId)}, ${sqlLiteral(key)}, ${sqlLiteral(JSON.stringify(defaultSettings[key]))}::jsonb)`,
  );
  return [
    '-- GENERATED by `pnpm gen:seed` from packages/core/src/settings/defaults.ts. Do not edit by hand.',
    'insert into public.settings (tenant_id, key, value) values',
    rows.join(',\n'),
    'on conflict (tenant_id, key) do nothing;',
    '',
  ].join('\n');
}
